-- Read-only audit for Supabase E2E. Do not run against production.
with roles(role_name) as (values ('anon'::name),('authenticated'::name),('service_role'::name)) select ns.nspname as table_schema, cls.relname as table_name, roles.role_name, has_table_privilege(roles.role_name,cls.oid,'SELECT') as select_privilege, has_table_privilege(roles.role_name,cls.oid,'INSERT') as insert_privilege, has_table_privilege(roles.role_name,cls.oid,'UPDATE') as update_privilege, has_table_privilege(roles.role_name,cls.oid,'DELETE') as delete_privilege, has_table_privilege(roles.role_name,cls.oid,'TRUNCATE') as truncate_privilege, has_table_privilege(roles.role_name,cls.oid,'REFERENCES') as references_privilege, has_table_privilege(roles.role_name,cls.oid,'TRIGGER') as trigger_privilege, cls.relrowsecurity as rls_enabled, (select count(*) from pg_policies pol where pol.schemaname='public' and pol.tablename=cls.relname) as applicable_policy_count from pg_class cls join pg_namespace ns on ns.oid=cls.relnamespace cross join roles where ns.nspname='public' and cls.relkind in ('r','p') order by cls.relname,roles.role_name;
